def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==2 and all(grid[r+dr][c+dc]==3 for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]):
                for j in range(w):
                    if grid[r][j]==0: out[r][j]=1
                for i in range(h):
                    if grid[i][c]==0: out[i][c]=1
    return out
